@Component({
  selector: 'app-offline-mutation-queue',
  template: '',
  standalone: true
})
export class OfflineMutationQueueComponent {
  // Define the Mutation interface here
  interface Mutation {
    id: number;
    type: string;
    payload: any;
    status: 'pending' | 'syncing' | 'synced' | 'failed';
  }

  // Initialize the mutation queue array here
  mutations: Mutation[] = [];

  // Initialize the online status state here
  isOnline: boolean = true;

  // Create the addMutation handler here
  addMutation() {
    const newMutation: Mutation = {
      id: Date.now(),
      type: 'UPDATE',
      payload: { data: 'Sample data' },
      status: 'pending'
    };
    this.mutations.push(newMutation);
  }

  // Create the processQueue handler here
  processQueue() {
    if (!this.isOnline) {
      console.log('Offline - queue processing paused');
      return;
    }
    this.mutations.forEach(mutation => {
      if (mutation.status === 'pending') {
        mutation.status = 'syncing';
        // Simulate API call
        setTimeout(() => {
          mutation.status = 'synced';
        }, 1000);
      }
    });
  }

  // Create the toggleOnlineStatus handler here
  toggleOnlineStatus() {
    this.isOnline = !this.isOnline;
  }
}

